<?php
session_start();
if(empty($_SESSION['user_id'])){header('Location:/pages/login.php');exit;}
require_once __DIR__.'/../config/config.php';
$number=trim($_GET['number']??'');
$stmt=$pdo->prepare('SELECT * FROM orders WHERE order_number=? AND user_id=?');$stmt->execute([$number,(int)$_SESSION['user_id']]);$order=$stmt->fetch(PDO::FETCH_ASSOC);
if(!$order){http_response_code(404);exit('ไม่พบข้อมูลคำสั่งซื้อ');}
$items=$pdo->prepare('SELECT oi.quantity,oi.price_at_purchase,b.title,b.author FROM order_items oi LEFT JOIN books b ON b.book_id=oi.book_id WHERE oi.order_id=?');$items->execute([$order['order_id']]);$items=$items->fetchAll(PDO::FETCH_ASSOC);
$shippingLabels=['pending'=>'รอเตรียมสินค้า','packing'=>'กำลังเตรียมจัดส่ง','shipped'=>'กำลังจัดส่ง','delivered'=>'จัดส่งสำเร็จ','returned'=>'ตีกลับ/คืนสินค้า','cancelled'=>'ยกเลิกแล้ว'];
if($order['payment_status']==='cancelled'||$order['shipping_status']==='cancelled'){$pay='ยกเลิกคำสั่งซื้อ';$statusClass='cancelled';}
elseif($order['shipping_status']==='delivered'){$pay='จัดส่งสำเร็จแล้ว';$statusClass='success';}
elseif($order['shipping_status']==='shipped'){$pay='กำลังจัดส่ง';$statusClass='shipping';}
elseif($order['shipping_status']==='packing'){$pay='กำลังเตรียมสินค้า';$statusClass='packing';}
elseif($order['payment_status']==='reviewing'){$pay='รอตรวจสอบการชำระเงิน';$statusClass='reviewing';}
elseif($order['payment_status']==='paid'){$pay='ชำระเงินแล้ว';$statusClass='paid';}
else{$pay='รอชำระเงิน';$statusClass='pending';}
$shippingText=$shippingLabels[$order['shipping_status']]??$order['shipping_status'];
$discount=(float)$order['subtotal']+(float)$order['shipping_fee']-(float)$order['total_amount'];
?>
<!DOCTYPE html><html lang="th"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ใบคำสั่งซื้อ <?=htmlspecialchars($number)?></title><link rel="stylesheet" href="../assets/css/styles.css"><style>*{box-sizing:border-box}body{background:#eee9e4}.receipt-wrap{max-width:760px;margin:45px auto;padding:0 18px}.paper{background:#fff;box-shadow:0 8px 30px rgba(64,50,42,.14);padding:48px 52px;position:relative}.paper:after{content:'';position:absolute;left:0;right:0;bottom:-10px;height:20px;background:linear-gradient(135deg,#fff 10px,transparent 0) 0 0/20px 20px repeat-x}.head{display:flex;justify-content:space-between;gap:30px;padding-bottom:25px;border-bottom:2px solid #175f6d}.brand{display:flex;align-items:center;gap:12px}.brand img{width:80px}.brand h1{margin:0;color:#175f6d;font-size:27px}.brand p,.meta p{margin:3px 0;color:#777;font-size:13px}.meta{text-align:right}.status{display:inline-block;padding:7px 14px;border-radius:20px;background:#f7dfe8;color:#a64d70;font-weight:600;margin-top:8px}.status.shipping,.status.packing{background:#fff0d8;color:#9b681d}.status.success{background:#e6f3e2;color:#39713b}.status.cancelled{background:#fde3df;color:#b63f3a}.status.reviewing{background:#fff1cf;color:#9a6b16}.info{display:grid;grid-template-columns:1fr 1fr;gap:35px;margin:30px 0}.info h2{font-size:15px;color:#175f6d;margin:0 0 8px}.info p{margin:3px 0;color:#5f5853;line-height:1.6}.tracking{margin:0 0 28px;padding:16px 18px;border:1px solid #bad2c1;border-radius:10px;background:#f0f7f1;color:#356240}.tracking strong{display:block;color:#175f6d;margin-bottom:6px}.tracking-number{font-size:18px;font-weight:700;letter-spacing:.6px}.table{width:100%;border-collapse:collapse}.table th{padding:12px 8px;text-align:left;background:#f8eee9;color:#175f6d}.table td{padding:14px 8px;border-bottom:1px solid #eee}.right{text-align:right!important}.totals{width:min(330px,100%);margin:24px 0 0 auto}.total-row{display:flex;justify-content:space-between;padding:8px}.grand{border-top:2px solid #175f6d;margin-top:5px;padding-top:14px;color:#175f6d;font-size:22px;font-weight:700}.thanks{text-align:center;margin-top:40px;padding-top:22px;border-top:1px dashed #bbb;color:#777}.actions{text-align:center;margin:30px}.print{border:0;border-radius:9px;padding:13px 25px;background:#175f6d;color:#fff;font:inherit;cursor:pointer}@media(max-width:600px){.paper{padding:30px 22px}.head,.info{display:block}.meta{text-align:left;margin-top:18px}.info>div{margin-top:20px}.table th:nth-child(2),.table td:nth-child(2){display:none}}@media print{body{background:#fff}.site-header,.site-footer,.actions{display:none!important}.receipt-wrap{margin:0;max-width:none;padding:0}.paper{box-shadow:none;padding:20px}.paper:after{display:none}}</style></head><body>
<?php require __DIR__.'/../components/header.php';?><main class="receipt-wrap"><article class="paper"><header class="head"><div class="brand"><img src="/assets/image/logo.png" alt="วนวรรณ"><div><h1>ใบคำสั่งซื้อ</h1><p>วนวรรณ Buy • Sell • Exchange</p></div></div><div class="meta"><p><strong>เลขที่ <?=htmlspecialchars($order['order_number'])?></strong></p><p>วันที่ <?=date('d/m/Y H:i',strtotime($order['created_at']))?></p><span class="status <?=htmlspecialchars($statusClass)?>"><?=htmlspecialchars($pay)?></span></div></header><section class="info"><div><h2>ข้อมูลผู้รับ</h2><p><strong><?=htmlspecialchars($order['shipping_name'])?></strong><br><?=nl2br(htmlspecialchars($order['shipping_address']))?><br>โทร: <?=htmlspecialchars($order['shipping_phone'])?></p></div><div><h2>ข้อมูลการจัดส่งและชำระเงิน</h2><p>วิธีจัดส่ง: <?=htmlspecialchars($order['shipping_method'])?><br>ชำระผ่าน: PromptPay<br>สถานะจัดส่ง: <strong><?=htmlspecialchars($shippingText)?></strong><?php if($order['paid_at']):?><br>ตรวจสอบการชำระเงินเมื่อ: <?=date('d/m/Y H:i',strtotime($order['paid_at']))?><?php endif;?></p></div></section><?php if(!empty($order['tracking_number'])):?><section class="tracking"><strong>ข้อมูลติดตามพัสดุ</strong><div>บริษัทขนส่ง: <?=htmlspecialchars($order['shipping_courier']?:'ไม่ระบุ')?></div><div>หมายเลขพัสดุ: <span class="tracking-number"><?=htmlspecialchars($order['tracking_number'])?></span></div><?php if($order['shipped_at']):?><div>วันที่ส่งสินค้า: <?=date('d/m/Y H:i',strtotime($order['shipped_at']))?></div><?php endif;?></section><?php endif;?><table class="table"><thead><tr><th>รายการ</th><th>ราคาต่อเล่ม</th><th class="right">จำนวน</th><th class="right">รวม</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><strong><?=htmlspecialchars($item['title']?:'หนังสือ')?></strong><br><small><?=htmlspecialchars($item['author']?:'')?></small></td><td>฿<?=number_format($item['price_at_purchase'],2)?></td><td class="right"><?=$item['quantity']?></td><td class="right">฿<?=number_format($item['price_at_purchase']*$item['quantity'],2)?></td></tr><?php endforeach;?></tbody></table><div class="totals"><div class="total-row"><span>ยอดรวมสินค้า</span><span>฿<?=number_format($order['subtotal'],2)?></span></div><div class="total-row"><span>ค่าจัดส่ง</span><span>฿<?=number_format($order['shipping_fee'],2)?></span></div><div class="total-row"><span>ส่วนลดสมาชิก</span><span>− ฿<?=number_format(max(0,$discount),2)?></span></div><div class="total-row grand"><span>ยอดสุทธิ</span><span>฿<?=number_format($order['total_amount'],2)?></span></div></div><div class="thanks">ขอบคุณที่เลือกซื้อและส่งต่อเรื่องราวดี ๆ กับวนวรรณ</div></article><div class="actions"><button class="print" onclick="window.print()">พิมพ์หรือบันทึกเป็น PDF</button></div></main><?php require __DIR__.'/../components/footer.php';?></body></html>
